python3 -c "
import json,os
found=[]
def walk(o):
    if isinstance(o,dict):
        if str(o.get('type','')).startswith('urn:agentic:problem:') and 'status' in o and 'title' in o: found.append(o)
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
for root,dirs,files in os.walk('.'):
    dirs[:]=[d for d in dirs if d not in ('.git','__pycache__')]
    for f in files:
        if not f.endswith(('.json','.jsonl')): continue
        p=os.path.join(root,f)
        try: txt=open(p,encoding='utf-8').read()
        except Exception: continue
        if 'urn:agentic:problem' not in txt: continue
        for line in ([txt] if f.endswith('.json') else txt.splitlines()):
            line=line.strip()
            if not line: continue
            try: walk(json.loads(line))
            except Exception: pass
u=[json.loads(s) for s in {json.dumps(o,sort_keys=True) for o in found}]
print('recorded problem bodies=%d  carrying correlation_id=%d  carrying an actor member=%d' % (len(u), sum(1 for o in u if o.get('correlation_id')), sum(1 for o in u if any(k in o for k in ('actor','subject','attested_subject')))))
"
